/**
 * Tests for Slack test helpers — fixture loader + mutator.
 *
 * Builder 0c (Wave 0c): tests must use real-shape Slack payloads. Helpers
 * in `test-helpers.ts` expose `loadFixture()` to read sanitized JSON from
 * `tests/fixtures/slack/` and `mutateFixture()` to deep-merge per-test overrides.
 */
import { describe, it, expect } from "vitest";
import {
  loadFixture,
  mutateFixture,
  makeSlackSignature,
  nowTimestamp,
} from "./test-helpers";

describe("makeSlackSignature / nowTimestamp (existing)", () => {
  it("nowTimestamp returns a string of digits", () => {
    const ts = nowTimestamp();
    expect(ts).toMatch(/^\d+$/);
  });

  it("makeSlackSignature returns a v0= prefixed hex", () => {
    const sig = makeSlackSignature("secret", "1700000000", "body");
    expect(sig).toMatch(/^v0=[0-9a-f]{64}$/);
  });
});

describe("loadFixture", () => {
  it("loads the view-submission-task fixture and exposes top-level Slack keys", () => {
    const fx = loadFixture<{
      type: string;
      team: { id: string };
      user: { id: string };
      view: { callback_id: string; private_metadata: string };
    }>("view-submission-task");

    expect(fx.type).toBe("view_submission");
    expect(fx.team.id).toBe("T_TEST_001");
    expect(fx.user.id).toBe("U_TEST_001");
    expect(fx.view.callback_id).toBe("runway_new_task");
    // private_metadata is a JSON-encoded string per Slack convention
    const meta = JSON.parse(fx.view.private_metadata);
    expect(meta.proposalId).toMatch(/^prop_/);
  });

  it("loads the block-actions-button-click fixture with action shape", () => {
    const fx = loadFixture<{
      type: string;
      actions: Array<{ action_id: string; value: string }>;
      trigger_id: string;
    }>("block-actions-button-click");
    expect(fx.type).toBe("block_actions");
    expect(fx.actions[0].action_id).toBe("open_create_modal");
    expect(fx.actions[0].value).toMatch(/^prop_/);
    expect(fx.trigger_id).toMatch(/^[0-9]+\.[0-9]+\.[0-9a-f]+$/);
  });

  it("loads the multi-detect-chain fixture as a 3-stage array", () => {
    const fx = loadFixture<
      Array<{ stage: string; payload: Record<string, unknown> }>
    >("block-actions-multi-detect-chain");
    expect(Array.isArray(fx)).toBe(true);
    expect(fx).toHaveLength(3);
    expect(fx[0].stage).toBe("project-button-click");
    expect(fx[1].stage).toBe("chat-update-after-project-saved");
    expect(fx[2].stage).toBe("child-task-button-click");
  });

  it("throws on missing fixture", () => {
    expect(() => loadFixture("does-not-exist")).toThrow();
  });
});

describe("mutateFixture", () => {
  it("deep-merges overrides without mutating original", () => {
    const fx = loadFixture<{
      type: string;
      user: { id: string; username: string };
    }>("view-submission-task");
    const originalUserId = fx.user.id;

    const mutated = mutateFixture(fx, {
      user: { id: "U_TEST_OVERRIDE" },
    });

    expect(mutated.user.id).toBe("U_TEST_OVERRIDE");
    // username preserved from original (deep-merge, not replace)
    expect(mutated.user.username).toBe(fx.user.username);
    // original untouched
    expect(fx.user.id).toBe(originalUserId);
  });

  it("supports overriding nested fields", () => {
    const base = { a: { b: { c: 1, d: 2 } }, e: 5 };
    const out = mutateFixture(base, { a: { b: { c: 99 } } });
    expect(out).toEqual({ a: { b: { c: 99, d: 2 } }, e: 5 });
    // original untouched
    expect(base.a.b.c).toBe(1);
  });

  it("replaces arrays wholesale (does not deep-merge arrays)", () => {
    const base = { tags: ["a", "b", "c"], other: 1 };
    const out = mutateFixture(base, { tags: ["x"] });
    expect(out.tags).toEqual(["x"]);
    expect(out.other).toBe(1);
  });
});

/**
 * Sanitization gate for Slack fixtures.
 *
 * Reads every fixture file under `tests/fixtures/slack/` and asserts none
 * contain real-shape Slack IDs. Real Slack IDs match patterns like
 *   - team:    `T` followed by 8-12 alphanumerics  (e.g. `T0CAG3KR4`)
 *   - user:    `U` followed by 8-12 alphanumerics  (e.g. `U02ABCD1234`)
 *   - channel: `C` / `D` / `G` followed by 8-12 alphanumerics
 *   - bot:     `B` followed by 8-12 alphanumerics
 *   - app:     `A` followed by 8-12 alphanumerics
 *   - view:    `V` followed by 8-12 alphanumerics
 *   - enterprise: `E` followed by 8-12 alphanumerics
 *
 * Sanitized fixtures use the explicit prefix `_TEST_` (e.g. `T_TEST_001`,
 * `U_TEST_001`, `C_TEST_001`, `V_TEST_001`) so the underscore breaks the
 * real-shape regex. Trigger IDs follow Slack shape (`<int>.<int>.<hex>`)
 * but use obvious test values so they can't conflict with real prod data.
 *
 * Any new fixture that fails this gate must be re-sanitized before commit.
 */

import { describe, it, expect } from "vitest";
import { readFileSync, readdirSync } from "fs";
import { join } from "path";

const FIXTURE_DIR = join(__dirname, "slack");

// Match real-shape Slack IDs:
//   prefix letter then 8-12 alphanumerics (uppercase letters + digits),
//   not preceded by `_` or letter (so `T_TEST_001` and `BOT123` don't match),
//   not followed by alphanumeric (so we land on a full ID, not a substring).
//
// Slack IDs are 9-11 chars typically; we widen to 8-12 for safety. We do NOT
// match shorter values so we don't false-positive on `B0` etc.
const REAL_ID_REGEX = /(?<![A-Za-z0-9_])([TUCDGBAEV])([0-9A-Z]{8,12})(?![A-Za-z0-9])/g;

// Allow-list: known Slack-shape sanitized values that happen to look real-ish
// but are obviously test values. Empty for now — `_TEST_` prefix breaks the
// regex naturally (the underscore is excluded by the `[0-9A-Z]` body class).
const ALLOWED_LITERALS: ReadonlySet<string> = new Set();

function findRealShapeIds(text: string): string[] {
  const hits: string[] = [];
  for (const m of text.matchAll(REAL_ID_REGEX)) {
    const literal = m[0];
    if (ALLOWED_LITERALS.has(literal)) continue;
    hits.push(literal);
  }
  return hits;
}

describe("Slack fixture sanitization gate", () => {
  const files = readdirSync(FIXTURE_DIR).filter((f) => f.endsWith(".json"));

  it("has the expected fixture files", () => {
    const expected = [
      "block-actions-button-click.json",
      "block-actions-checkbox-toggle.json",
      "block-actions-multi-detect-chain.json",
      "view-submission-task.json",
      "view-submission-project.json",
      "view-submission-retainer.json",
      "view-submission-team-member.json",
      "view-closed.json",
      "slash-command-create.json",
      "slash-command-edit-multimatch.json",
      "event-callback-message.json",
    ];
    for (const name of expected) {
      expect(files, `expected fixture file: ${name}`).toContain(name);
    }
  });

  for (const file of files) {
    it(`${file} parses as valid JSON`, () => {
      const raw = readFileSync(join(FIXTURE_DIR, file), "utf-8");
      expect(() => JSON.parse(raw)).not.toThrow();
    });

    it(`${file} contains no real-shape Slack IDs`, () => {
      const raw = readFileSync(join(FIXTURE_DIR, file), "utf-8");
      const hits = findRealShapeIds(raw);
      expect(
        hits,
        `Fixture ${file} contains real-shape Slack IDs: ${hits.join(", ")}. ` +
          `Use the _TEST_ sanitization prefix (e.g. T_TEST_001).`
      ).toEqual([]);
    });

    it(`${file} uses sanitized team/user/channel/view IDs where present`, () => {
      const raw = readFileSync(join(FIXTURE_DIR, file), "utf-8");
      const json = JSON.parse(raw) as unknown;

      // Recursively walk and collect any value at sensitive keys.
      const collected: Array<{ key: string; value: string }> = [];
      const walk = (node: unknown): void => {
        if (Array.isArray(node)) {
          for (const item of node) walk(item);
          return;
        }
        if (node && typeof node === "object") {
          for (const [k, v] of Object.entries(node as Record<string, unknown>)) {
            if (typeof v === "string") {
              if (
                k === "team_id" ||
                k === "user_id" ||
                k === "channel_id" ||
                k === "view_id"
              ) {
                collected.push({ key: k, value: v });
              }
            }
            walk(v);
          }
        }
      };
      walk(json);

      for (const { key, value } of collected) {
        // Must include _TEST_ marker
        expect(
          value,
          `${file}: ${key}=${value} must contain '_TEST_' marker`
        ).toMatch(/_TEST_/);
      }
    });
  }
});

/**
 * Shared test utilities for Slack-related tests.
 *
 * Used by:
 *   - verify.test.ts (HMAC signature checks)
 *   - events/route.test.ts (request construction)
 *   - Wave 0c onward — `loadFixture` / `mutateFixture` for sanitized real-shape
 *     Slack payload fixtures stored under `tests/fixtures/slack/`.
 */

import { createHmac } from "crypto";
import { readFileSync } from "fs";
import { join } from "path";

export function makeSlackSignature(
  secret: string,
  timestamp: string,
  body: string
): string {
  const baseString = `v0:${timestamp}:${body}`;
  return "v0=" + createHmac("sha256", secret).update(baseString).digest("hex");
}

export function nowTimestamp(): string {
  return Math.floor(Date.now() / 1000).toString();
}

/**
 * Resolve the absolute path to a fixture file under `tests/fixtures/slack/`.
 *
 * `name` may be supplied with or without the `.json` extension.
 */
function fixturePath(name: string): string {
  const file = name.endsWith(".json") ? name : `${name}.json`;
  // From `<repo>/src/lib/slack/test-helpers.ts`, fixtures live at
  // `<repo>/tests/fixtures/slack/`. Resolve via `__dirname` so this works
  // under Vitest regardless of CWD.
  return join(__dirname, "..", "..", "..", "tests", "fixtures", "slack", file);
}

/**
 * Read a sanitized Slack payload fixture from `tests/fixtures/slack/`.
 *
 * The generic `T` lets callers pin the expected shape. The function only
 * parses + returns — schema validation is the caller's responsibility.
 *
 * Throws if the file does not exist or is not valid JSON.
 */
export function loadFixture<T = unknown>(name: string): T {
  const raw = readFileSync(fixturePath(name), "utf-8");
  return JSON.parse(raw) as T;
}

/**
 * Internal type guard: a non-array, non-null object.
 */
function isPlainObject(v: unknown): v is Record<string, unknown> {
  return typeof v === "object" && v !== null && !Array.isArray(v);
}

/**
 * Deep-merge `overrides` into a copy of `base` and return the copy.
 *
 * Semantics:
 *   - Plain objects are merged recursively.
 *   - Arrays are replaced wholesale (no element-wise merge).
 *   - Primitives in `overrides` win over `base`.
 *   - The original `base` is never mutated.
 *
 * Typical use:
 *   const fx = loadFixture<ViewSubmission>("view-submission-task");
 *   const stale = mutateFixture(fx, { view: { private_metadata: "..." } });
 */
export function mutateFixture<T>(base: T, overrides: Partial<T>): T {
  return deepMerge(base, overrides) as T;
}

function deepMerge(base: unknown, overrides: unknown): unknown {
  if (!isPlainObject(base) || !isPlainObject(overrides)) {
    // Non-object override (or non-object base) → override wins.
    return overrides === undefined ? base : overrides;
  }
  const out: Record<string, unknown> = { ...base };
  for (const [k, v] of Object.entries(overrides)) {
    if (k in out && isPlainObject(out[k]) && isPlainObject(v)) {
      out[k] = deepMerge(out[k], v);
    } else {
      out[k] = v;
    }
  }
  return out;
}

